<section class="request"><h1>ورود / ثبت‌نام</h1><p class="hint">ورود با ایمیل برای حساب‌های قدیمی و مدیران</p><form method="post"><?= Namira\Security::field() ?><input type="hidden" name="action" value="login"><input type="hidden" name="next_page" value="<?= e(is_string($_GET['next_page']??null)?$_GET['next_page']:'') ?>"><?php foreach(['call_id','martyr_id','id'] as $k): ?><input type="hidden" name="<?= $k ?>" value="<?= (int)($_GET[$k]??0) ?>"><?php endforeach ?><label for="email">ایمیل</label><input id="email" name="email" type="email" autocomplete="username" required><label for="password">رمز عبور</label><input id="password" name="password" type="password" autocomplete="current-password" required><button class="primary">ورود</button></form><p><a class="outline" href="<?= e(url('register',['next_page'=>is_string($_GET['next_page']??null)?$_GET['next_page']:'account','call_id'=>(int)($_GET['call_id']??0),'martyr_id'=>(int)($_GET['martyr_id']??0)])) ?>">ساخت حساب برای ارسال اثر و مشارکت</a></p></section>
